import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"فهرس المواد القانونية","description":"","frontmatter":{},"headers":[],"relativePath":"ar/92-法律条文索引.md","filePath":"ar/92-法律条文索引.md","lastUpdated":null}'),h={name:"ar/92-法律条文索引.md"};function l(o,t,i,b,n,s){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="فهرس-المواد-القانونية" tabindex="-1">فهرس المواد القانونية <a class="header-anchor" href="#فهرس-المواد-القانونية" aria-label="Permalink to &quot;فهرس المواد القانونية&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>92</td></tr><tr><td>الوحدة</td><td>الملاحق والمواد المرجعية</td></tr><tr><td>الكلمات المفتاحية</td><td>الفهرس القانوني، الدستور التكافلي، قانون العمل، قانون حماية المستهلك، القوانين المرافقة</td></tr></tbody></table><h2 id="أولاً-ملاحظات-حول-الفهرس" tabindex="-1">أولاً: ملاحظات حول الفهرس <a class="header-anchor" href="#أولاً-ملاحظات-حول-الفهرس" aria-label="Permalink to &quot;أولاً: ملاحظات حول الفهرس&quot;">​</a></h2><p>يجمع هذا الفهرس الوثائق القانونية الرئيسية السارية في حضارة التكافل المرساة وموادها الجوهرية، مصنفة حسب التسلسل القانوني والتخصص. يغطي نطاق الفهرس الدستور التكافلي، وقانون العمل التكافلي، وقانون حماية المستهلك، إضافة إلى خمسة قوانين مرافقة هي التعليم والرعاية الطبية والإسكان والبيئة ومكافحة الاحتكار. تذكر كل مدخلة اسم القانون ورقم المادة وملخصاً للمحتوى الجوهري للمادة. هذا الفهرس أداة استرشاد؛ أما النص الكامل للمواد القانونية والتفسيرات القضائية فتراجع في النصوص الرسمية للقوانين المعنية.</p><h2 id="ثانياً-الدستور-التكافلي" tabindex="-1">ثانياً: الدستور التكافلي <a class="header-anchor" href="#ثانياً-الدستور-التكافلي" aria-label="Permalink to &quot;ثانياً: الدستور التكافلي&quot;">​</a></h2><p>الدستور التكافلي هو القانون الأساسي لحضارة التكافل المرساة، يتمتع بأعلى قوة قانونية، ووُضع عند التأسيس الرسمي للحضارة التكافلية.</p><table tabindex="0"><thead><tr><th>رقم المادة</th><th>المحتوى الجوهري</th></tr></thead><tbody><tr><td>المادة الأولى</td><td>يثبت كون هنغ يوان (الكون الأصلاني وانلينغ هنغماو) مجال حكم حضارة التكافل المرساة؛ والغرض الأساسي للحضارة التكافلية هو تحقيق تكافل عشرة آلاف عرق وارتقاء الكون</td></tr><tr><td>المادة الثانية</td><td>يثبت معاداة الافتراس موقفاً أساسياً للحضارة، ويحظر الزراعة الافتراسية ونهب الموارد بأي شكل</td></tr><tr><td>المادة الثالثة</td><td>يثبت «إعادة حق اختيار المصير والتطور إلى جميع الكائنات الحية» مفهوماً جوهرياً للحضارة</td></tr><tr><td>المادة الرابعة</td><td>يثبت عملاً أكثر ربحاً أكثر، ونمواً ذاتياً، وطريقاً لكل فرد، وتقدماً مشتركاً لعشرة آلاف عرق سياسات أساسية للحضارة</td></tr><tr><td>المادة الخامسة</td><td>يثبت نظام الفتح المجاني لأنظمة الزراعة الأصلانية الثلاثمائة؛ ولا يجوز لأي منظمة أو فرد احتكار حقوق نقل أنظمة الزراعة</td></tr><tr><td>المادة السادسة</td><td>يثبت آلية العقود المرتبطة بالإنتاج نظاماً أساسياً لتوزيع الموارد</td></tr><tr><td>المادة السابعة</td><td>يثبت استراتيجية التنشيط بنسبة 20٪ هدفاً وطنياً مرحلياً</td></tr><tr><td>المادة الثامنة</td><td>يثبت مبدأ الواقع أساس: العالم الواقعي هو العالم الحقيقي الوحيد، ولا قوة قانونية للإعدادات الخيالية</td></tr><tr><td>المادة التاسعة</td><td>يثبت مسار الارتقاء بأربع مراحل استراتيجية تنمية طويلة الأمد للحضارة</td></tr><tr><td>المادة العاشرة</td><td>يثبت مبدأ مساواة عشرة آلاف عرق؛ جميع أشكال الحياة متساوية أمام القانون</td></tr><tr><td>المادة الحادية عشرة</td><td>يثبت مبدأ التطور التكافلي؛ لا يجوز أن يتم التطور الفردي على حساب حقوق تطور أفراد أو جماعات أخرى</td></tr><tr><td>المادة الثانية عشرة</td><td>يثبت مبدأ عملاً أكثر ربحاً أكثر؛ يقوم توزيع الموارد على المساهمة كأساس جوهري</td></tr><tr><td>المادة الثالثة عشرة</td><td>يثبت مبدأ النمو الذاتي؛ يحترم حق كل كائن حي في الاختيار الذاتي للتطور</td></tr><tr><td>المادة الرابعة عشرة</td><td>يثبت مبدأ طريق لكل فرد؛ على الدولة واجب توفير مسار تطور أساسي وضمان موارد لكل كائن حي</td></tr><tr><td>المادة الخامسة عشرة</td><td>يثبت مبدأ الاستدامة؛ يجب أن تراعي جميع التنمية استدامة أصل الكون</td></tr><tr><td>المواد من السادسة عشرة إلى الخامسة والعشرين</td><td>تحدد الحقوق الأساسية للكائنات الحية: حق اختيار التطور، حق الحصول على موارد الزراعة، حق الحماية المتساوية، حق المشاركة في التكافل، حق الحفاظ على الثقافة، حق الإنقاذ والطعن، حق الحرية الشخصية، حق كرامة الشخص، حق حرية العقيدة، حق حرية التعبير</td></tr><tr><td>المواد من السادسة والعشرين إلى الحادية والثلاثين</td><td>تحدد الواجبات الأساسية للكائنات الحية: واجب الالتزام بالقانون، واجب الحفاظ على النظام التكافلي، واجب المساهمة بالعمل، واجب حماية البيئة، واجب احترام حقوق الآخرين، واجب إرشاد المزارعين المبتدئين</td></tr><tr><td>المادة الثانية والثلاثون</td><td>يثبت المجلس التشريعي للمرساة أعلى هيئة سلطة، يتكون من ممثلين عن عشرة آلاف عرق بنسب متوازنة</td></tr><tr><td>المادة الثالثة والثلاثون</td><td>يثبت اللجنة التنفيذية التكافلية أعلى هيئة إدارية</td></tr><tr><td>المادة الرابعة والثلاثون</td><td>يثبت محكمة التكافل أعلى هيئة قضائية، تمارس السلطة القضائية باستقلال</td></tr><tr><td>المادة الخامسة والثلاثون</td><td>يثبت لجنة الرقابة للمرساة هيئة رقابية مستقلة</td></tr><tr><td>المادة السادسة والثلاثون</td><td>يحدد الإجراء التشريعي: يُمرَّر مشروع القانون بأغلبية تزيد على نصف المجلس التشريعي للمرساة</td></tr><tr><td>المادة السابعة والثلاثون</td><td>يحدد إجراء تعديل الدستور: يجب إقراره بأغلبية تزيد على ثلثي المجلس التشريعي للمرساة وموافقة أكثر من نصف الشعب في استفتاء عام</td></tr><tr><td>المادة الثامنة والثلاثون</td><td>يثبت نظام مراجعة دستورية القوانين؛ يحق لمحكمة التكافل إعلان بطلان القوانين المخالفة للدستور</td></tr><tr><td>المادة التاسعة والثلاثون</td><td>يثبت نظام التقاضي الدستوري؛ يحق لجميع الكائنات الحية رفع دعاوى مباشرة وفق الدستور</td></tr><tr><td>المادة الأربعون</td><td>يحدد نظام الحكم الذاتي المحلي؛ تطبق كل منطقة نجمية وكل بُعد الحكم الذاتي في إطار الدستور</td></tr><tr><td>المادة الحادية والأربعون</td><td>يثبت نظام جمهورية عشرة آلاف عرق؛ جميع الأعراق متساوية في الحضارة التكافلية وتطبق الحكم الذاتي الإقليمي</td></tr><tr><td>المادة الثانية والأربعون</td><td>يحدد النظام الاقتصادي للحضارة التكافلية: بالاستناد إلى العقود المرتبطة بالإنتاج، مع تنمية مشتركة لأشكال ملكية متعددة</td></tr><tr><td>المادة الثالثة والأربعون</td><td>يحدد نظام ملكية الدولة لموارد الزراعة وتوزيعها العادل</td></tr><tr><td>المادة الرابعة والأربعون</td><td>يثبت نظام عدالة التعليم، ويضمن لكل كائن حي حق التعليم المتساوي</td></tr><tr><td>المادة الخامسة والأربعون</td><td>يثبت نظام الضمان الطبي الشامل</td></tr><tr><td>المادة السادسة والأربعون</td><td>يثبت نظام ضمان الإسكان، ويضمن لكل كائن حي حق السكن الأساسي</td></tr><tr><td>المادة السابعة والأربعون</td><td>يحدد المبادئ الأساسية للتفاعل عبر الأبعاد؛ يحظر التنقل عبر الأبعاد دون إذن</td></tr><tr><td>المادة الثامنة والأربعون</td><td>يحدد أن النواتج المشروعة للأنشطة الأثرية تقتصر على المعرفة والمعلومات المجردة؛ ويحظر إعادة المادة والطاقة</td></tr><tr><td>المادة التاسعة والأربعون</td><td>يحدد المبادئ الأساسية للارتداد الزمني؛ يجب اتباع مبدأ الملاحظة أولاً ثم التدخل المحدود</td></tr><tr><td>المادة الخمسون</td><td>يحدد أن حق تفسير الدستور يعود لمحكمة التكافل، وحق تعديل الدستور يعود للمجلس التشريعي للمرساة</td></tr></tbody></table><h2 id="ثالثاً-قانون-العمل-التكافلي" tabindex="-1">ثالثاً: قانون العمل التكافلي <a class="header-anchor" href="#ثالثاً-قانون-العمل-التكافلي" aria-label="Permalink to &quot;ثالثاً: قانون العمل التكافلي&quot;">​</a></h2><p>قانون العمل التكافلي هو القانون الأساسي الذي ينظم علاقات العمل ويحمي حقوق ومصالح العمال، ووُضع على أساس تشريعي هو المادة الثانية والأربعون من الدستور التكافلي.</p><table tabindex="0"><thead><tr><th>رقم المادة</th><th>المحتوى الجوهري</th></tr></thead><tbody><tr><td>المادة الأولى</td><td>الغرض التشريعي: تنظيم علاقات العمل، حماية الحقوق والمصالح المشروعة للعمال، وبناء علاقات عمل متناغمة تكافلية</td></tr><tr><td>المادة الثانية</td><td>نطاق التطبيق: جميع علاقات العمل في كون هنغ يوان، بما فيها العمل المادي وعمل الزراعة والعمل الإبداعي</td></tr><tr><td>المادة الثالثة</td><td>يثبت مبدأ المساواة في التوظيف للعمال؛ يحظر التمييز الوظيفي القائم على العرق أو الجنس أو مستوى الزراعة أو الأصل</td></tr><tr><td>المادة الرابعة</td><td>يثبت مبدأ حرية اختيار العمل؛ يحظر العمل القسري والاستعباد</td></tr><tr><td>المادة الخامسة</td><td>يحدد نظام عقد العمل؛ يجب إبرام عقد عمل كتابي عند إنشاء علاقة عمل</td></tr><tr><td>المادة السادسة</td><td>يحدد الشروط الإلزامية لعقد العمل: مدة العقد، محتوى العمل، الأجر، ساعات العمل، حماية العمل، التأمين الاجتماعي</td></tr><tr><td>المادة السابعة</td><td>يثبت يوم العمل ثماني ساعات ونظام ساعات عمل لا تتجاوز أربعاً وأربعين ساعة أسبوعياً</td></tr><tr><td>المادة الثامنة</td><td>يحدد قيود العمل الإضافي: لا يتجاوز ساعة واحدة يومياً، وثلاث ساعات في الحالات الخاصة، ولا يتجاوز ستاً وثلاثين ساعة شهرياً</td></tr><tr><td>المادة التاسعة</td><td>يحدد معايير أجر العمل الإضافي: أجر العمل الإضافي في أيام العمل 1.5 ضعف، وفي أيام الراحة ضعفان، وفي الأعياد الرسمية ثلاثة أضعاف</td></tr><tr><td>المادة العاشرة</td><td>يثبت نظام ضمان الحد الأدنى للأجور؛ تحدد كل منطقة نجمية معيار الحد الأدنى للأجور وفق ظروفها المحلية</td></tr><tr><td>المادة الحادية عشرة</td><td>يحدد نظام صرف الأجور: يصرف الأجر شهرياً للعامل شخصياً بعملة نقدية، دون اقتطاع أو تأخير بلا سبب</td></tr><tr><td>المادة الثانية عشرة</td><td>يثبت مبدأ التوزيع عملاً أكثر ربحاً أكثر؛ يطبق نظام توزيع يكون التوزيع حسب العمل أساسه وتتعدد فيه أساليب التوزيع</td></tr><tr><td>المادة الثالثة عشرة</td><td>يحدد نظام سلامة وصحة العمل؛ يجب على أصحاب العمل توفير شروط سلامة وصحة عمل مطابقة للمعايير للعمال</td></tr><tr><td>المادة الرابعة عشرة</td><td>يحدد حماية الفئات الخاصة: حماية عمل خاصة للعمال القاصرين والعاملات والعمال ذوي الإعاقة والعمال منخفضي مستوى الزراعة</td></tr><tr><td>المادة الخامسة عشرة</td><td>يثبت نظام التدريب المهني؛ على أصحاب العمل واجب تدريب العمال على المهارات المهنية</td></tr><tr><td>المادة السادسة عشرة</td><td>يحدد حقوق عمل المزارعين: عمل الزراعة محمي بهذا القانون بالتساوي، وتحدد ملكية نتائج الزراعة بالعقد</td></tr><tr><td>المادة السابعة عشرة</td><td>يثبت نظام التأمين الاجتماعي للعمال: تأمين التقاعد، التأمين الطبي، تأمين البطالة، تأمين إصابات العمل، تأمين الأمومة</td></tr><tr><td>المادة الثامنة عشرة</td><td>يحدد نظام مزايا العمال: على أصحاب العمل توفير المزايا اللازمة للعمال</td></tr><tr><td>المادة التاسعة عشرة</td><td>يثبت نظام معالجة منازعات العمل: آلية معالجة رباعية المستويات هي التفاوض والوساطة والتحكيم والتقاضي</td></tr><tr><td>المادة العشرون</td><td>يحدد نظام النقابات؛ يحق للعمال تشكيل النقابات والانضمام إليها وفق القانون لحماية حقوقهم ومصالحهم المشروعة</td></tr><tr><td>المادة الحادية والعشرون</td><td>يحدد نظام العقد الجماعي؛ تمثل النقابات العمال في إبرام العقود الجماعية مع أصحاب العمل</td></tr><tr><td>المادة الثانية والعشرون</td><td>يحدد أن اللوائح الداخلية لصاحب العمل يجب أن تناقشها مؤتمر العمال أو جميع العمال</td></tr><tr><td>المادة الثالثة والعشرون</td><td>يحدد شروط وإجراءات إنهاء عقد العمل</td></tr><tr><td>المادة الرابعة والعشرون</td><td>يحدد نظام التعويض الاقتصادي؛ يدفع أصحاب العمل تعويضاً اقتصادياً عند إنهاء عقد العمل قانونياً</td></tr><tr><td>المادة الخامسة والعشرون</td><td>يحدد نظام تعويضات إنهاء عقد العمل بطرق غير قانونية</td></tr><tr><td>المادة السادسة والعشرون</td><td>يثبت نظام إدارة العمل المؤقت، وينظم تشغيل العمل المؤقت</td></tr><tr><td>المادة السابعة والعشرون</td><td>يحدد القواعد الخاصة للعمل غير المتفرغ</td></tr><tr><td>المادة الثامنة والعشرون</td><td>يحدد نظام الرقابة والتفتيش؛ تقوم الأجهزة الإدارية للعمل بالرقابة والتفتيش على التزام أصحاب العمل بقوانين العمل وفق القانون</td></tr><tr><td>المادة التاسعة والعشرون</td><td>يحدد المسؤولية القانونية: يتحمل أصحاب العمل المخالفون لهذا القانون مسؤولية إدارية ومدنية وجنائية وفق القانون</td></tr><tr><td>المادة الثلاثون</td><td>يحدد تاريخ نفاذ هذا القانون وحق تفسيره</td></tr></tbody></table><h2 id="رابعاً-قانون-حماية-المستهلك" tabindex="-1">رابعاً: قانون حماية المستهلك <a class="header-anchor" href="#رابعاً-قانون-حماية-المستهلك" aria-label="Permalink to &quot;رابعاً: قانون حماية المستهلك&quot;">​</a></h2><p>قانون حماية المستهلك هو القانون الأساسي الذي يحمي الحقوق والمصالح المشروعة للمستهلكين وينظم سلوك المشغلين الاقتصاديين.</p><table tabindex="0"><thead><tr><th>رقم المادة</th><th>المحتوى الجوهري</th></tr></thead><tbody><tr><td>المادة الأولى</td><td>الغرض التشريعي: حماية الحقوق والمصالح المشروعة للمستهلكين، والحفاظ على النظام الاقتصادي الاجتماعي، وتعزيز التنمية الصحية لاقتصاد السوق التكافلي</td></tr><tr><td>المادة الثانية</td><td>نطاق التطبيق: حماية حقوق ومصالح المستهلكين في كون هنغ يوان عند شراء واستخدام السلع أو تلقي الخدمات لحاجات الحياة اليومية</td></tr><tr><td>المادة الثالثة</td><td>يثبت المبادئ الأساسية للتعامل بين المشغلين والمستهلكين: الطوعية والمساواة والإنصاف وحسن النية</td></tr><tr><td>المادة الرابعة</td><td>يثبت مبدأ حماية الدولة للحقوق والمصالح المشروعة للمستهلكين؛ تتخذ الدولة إجراءات لضمان ممارسة المستهلكين حقوقهم وفق القانون</td></tr><tr><td>المادة الخامسة</td><td>يحدد الحقوق الأساسية التسعة للمستهلكين: حق السلامة، حق المعرفة، حق الاختيار الذاتي، حق التعامل العادل، حق التعويض، حق تكوين الجمعيات، حق اكتساب المعرفة، حق الاحترام، حق الرقابة</td></tr><tr><td>المادة السادسة</td><td>يحدد حق السلامة للمستهلك: يتمتع المستهلك عند شراء واستخدام السلع وتلقي الخدمات بحق عدم المساس بسلامته الشخصية والممتلكات</td></tr><tr><td>المادة السابعة</td><td>يحدد حق المعرفة للمستهلك: يتمتع المستهلك بحق معرفة الحقيقة الكاملة عن السلع التي يشتريها أو يستخدمها والخدمات التي يتلقاها</td></tr><tr><td>المادة الثامنة</td><td>يحدد حق الاختيار الذاتي للمستهلك: يتمتع المستهلك بحق اختيار السلع أو الخدمات بحرية</td></tr><tr><td>المادة التاسعة</td><td>يحدد حق التعامل العادل للمستهلك: يتمتع المستهلك بحق التعامل العادل ويحق له رفض التعاملات الإجبارية</td></tr><tr><td>المادة العاشرة</td><td>يحدد حق التعويض للمستهلك: المستهلك الذي يتعرض لضرر شخصي أو مالي بسبب شراء واستخدام السلع أو تلقي الخدمات يحق له الحصول على تعويض وفق القانون</td></tr><tr><td>المادة الحادية عشرة</td><td>يحدد الواجبات الأساسية للمشغلين: أداء الالتزامات القانونية والمتعاقد عليها، وقبول الرقابة، وضمان السلامة، وتقديم معلومات صحيحة، وإصدار الإيصالات، وضمان الجودة، وتنفيذ الضمانات الثلاث، وعدم التعامل غير العادل، وعدم انتهاك الكرامة الشخصية</td></tr><tr><td>المادة الثانية عشرة</td><td>يحدد واجب ضمان السلامة للمشغلين: يجب على المشغلين ضمان أن السلع أو الخدمات المقدمة منهم تستوفي متطلبات حماية السلامة الشخصية والممتلكات</td></tr><tr><td>المادة الثالثة عشرة</td><td>يحدد واجب الإفصاح عن المعلومات للمشغلين: يجب على المشغلين تقديم معلومات صحيحة عن السلع أو الخدمات للمستهلكين، دون إعلانات كاذبة أو مضللة</td></tr><tr><td>المادة الرابعة عشرة</td><td>يحدد القواعد الخاصة لمنتجات وخدمات الزراعة: يجب أن يمتلك مشغلو طرق الزراعة وأدوات الزراعة والمنتجات الطاقية مؤهلات خاصة، وأن تجتاز المنتجات شهادة السلامة</td></tr><tr><td>المادة الخامسة عشرة</td><td>يحدد تنظيم الشروط النموذجية: لا يجوز للمشغلين استخدام الشروط النموذجية لاستبعاد أو تقييد حقوق المستهلكين، أو للتخفيف من مسؤولية المشغل أو الإعفاء منها</td></tr><tr><td>المادة السادسة عشرة</td><td>يحدد نظام الإرجاع خلال سبعة أيام دون سبب: يحق للمستهلكين الذين يشترون سلعاً بطرق عن بُعد كالشبكة إرجاعها خلال سبعة أيام من تاريخ الاستلام</td></tr><tr><td>المادة السابعة عشرة</td><td>يحدد نظام الضمانات الثلاث: إذا كانت السلع أو الخدمات المقدمة من المشغلين لا تستوفي متطلبات الجودة، يجوز للمستهلكين طلب الإصلاح أو الاستبدال أو الإرجاع وفق اللوائح الوطنية</td></tr><tr><td>المادة الثامنة عشرة</td><td>يحدد نظام التعويض العقابي: إذا قدم المشغلون سلعاً أو خدمات بسلوك احتيالي، يجب عليهم وفق طلب المستهلكين زيادة تعويض الخسائر المتكبدة، ويكون مبلغ الزيادة ثلاثة أضعاف ثمن السلع المشتراة أو تكلفة الخدمات المتلقاة</td></tr><tr><td>المادة التاسعة عشرة</td><td>يحدد منظمات المستهلكين: جمعيات المستهلكين وغيرها من منظمات المستهلكين منظمات اجتماعية تأسست قانوناً للقيام برقابة اجتماعية على السلع والخدمات وحماية الحقوق والمصالح المشروعة للمستهلكين</td></tr><tr><td>المادة العشرون</td><td>يحدد سبل حل نزاعات الاستهلاك: التفاوض مع المشغل، وطلب الوساطة من جمعية المستهلكين، والتظلم لدى الأجهزة الإدارية المختصة، والإحالة إلى التحكيم، ورفع الدعوى أمام المحكمة</td></tr><tr><td>المادة الحادية والعشرون</td><td>يحدد قلب عبء الإثبات في النزاعات: بالنسبة للسلع المعمرة أو الخدمات كالديكور، إذا اكتشف المستهلكون عيوباً خلال ستة أشهر من الاستلام، يتحمل المشغل عبء الإثبات</td></tr><tr><td>المادة الثانية والعشرون</td><td>يحدد المسؤولية الإدارية والجنائية للمشغلين</td></tr><tr><td>المادة الثالثة والعشرون</td><td>يحدد تاريخ نفاذ هذا القانون وحق تفسيره</td></tr></tbody></table><h2 id="خامساً-القوانين-المرافقة-الخمسة" tabindex="-1">خامساً: القوانين المرافقة الخمسة <a class="header-anchor" href="#خامساً-القوانين-المرافقة-الخمسة" aria-label="Permalink to &quot;خامساً: القوانين المرافقة الخمسة&quot;">​</a></h2><h3 id="_5-1-قانون-ضمان-التعليم" tabindex="-1">5.1 قانون ضمان التعليم <a class="header-anchor" href="#_5-1-قانون-ضمان-التعليم" aria-label="Permalink to &quot;5.1 قانون ضمان التعليم&quot;">​</a></h3><table tabindex="0"><thead><tr><th>رقم المادة</th><th>المحتوى الجوهري</th></tr></thead><tbody><tr><td>المادة الأولى</td><td>الغرض التشريعي: ضمان حق التعليم المتساوي لجميع الكائنات الحية، بناء نظام تعليم تكافلي، وتعزيز التنمية المشتركة لثقافات عشرة آلاف عرق</td></tr><tr><td>المواد من الثانية إلى الخامسة</td><td>تثبت مبدأ عدالة التعليم، ومبدأ مجانية التعليم (في مرحلة التعليم الأساسي)، ومبدأ تنوع التعليم، ومبدأ الابتكار التعليمي</td></tr><tr><td>المواد من السادسة إلى العاشرة</td><td>تحدد البنية النظامية لتعليم ما قبل المدرسة والتعليم الإلزامي والتعليم الثانوي العالي والتعليم العالي وتعليم الزراعة</td></tr><tr><td>المواد من الحادية عشرة إلى الخامسة عشرة</td><td>تحدد الأنظمة الخاصة لتعليم الزراعة: القواعد التعليمية للأنظمة الثلاثمائة، ونظام الإرشاد، ونظام تخصيص موارد الزراعة</td></tr><tr><td>المواد من السادسة عشرة إلى العشرين</td><td>تحدد حقوق وواجبات المعلمين، ونظام مؤهلات المعلمين، وضمان معاملة المعلمين</td></tr><tr><td>المواد من الحادية والعشرين إلى الخامسة والعشرين</td><td>تحدد ضمان الاستثمار التعليمي، وبناء المرافق التعليمية، وميكنة التعليم، والتعليم الخاص، والتعليم بين الأعراق</td></tr><tr><td>المواد من السادسة والعشرين إلى الثلاثين</td><td>تحدد نظام تقييم التعليم، ونظام الرقابة على التعليم، والمسؤولية القانونية والأحكام الختامية</td></tr></tbody></table><h3 id="_5-2-قانون-الضمان-الطبي" tabindex="-1">5.2 قانون الضمان الطبي <a class="header-anchor" href="#_5-2-قانون-الضمان-الطبي" aria-label="Permalink to &quot;5.2 قانون الضمان الطبي&quot;">​</a></h3><table tabindex="0"><thead><tr><th>رقم المادة</th><th>المحتوى الجوهري</th></tr></thead><tbody><tr><td>المادة الأولى</td><td>الغرض التشريعي: إقامة نظام ضمان طبي شامل، وضمان حق الكائنات الحية في الصحة، ورفع المستوى الصحي الشامل لعشرة آلاف عرق</td></tr><tr><td>المواد من الثانية إلى الخامسة</td><td>تثبت مبدأ التأمين الطبي الشامل، ومبدأ مجانية الرعاية الطبية الأساسية، ومبدأ الجمع بين الطب الصيني والغربي، ومبدأ إدماج الطب الزراعي</td></tr><tr><td>المواد من السادسة إلى العاشرة</td><td>تحدد نظام التأمين الطبي متعدد المستويات: التأمين الطبي الأساسي، التأمين ضد الأمراض الكبرى، الإعانة الطبية، التأمين الصحي التجاري</td></tr><tr><td>المواد من الحادية عشرة إلى الخامسة عشرة</td><td>تحدد إدارة المؤسسات الطبية، ونظام الكوادر الطبية، وجودة وسلامة الرعاية الطبية، والقواعد الخاصة للطب الزراعي</td></tr><tr><td>المواد من السادسة عشرة إلى العشرين</td><td>تحدد إدارة الأدوية، وإدارة الأجهزة الطبية، وإدارة المنتجات الطبية الطاقية، ونظام الأدوية الأساسية</td></tr><tr><td>المواد من الحادية والعشرين إلى الخامسة والعشرين</td><td>تحدد نظام الصحة العامة، والوقاية من الأمراض والسيطرة عليها، والتثقيف الصحي، والطب بين الأعراق، والضمان الطبي للفئات الخاصة</td></tr><tr><td>المواد من السادسة والعشرين إلى الثلاثين</td><td>تحدد معالجة النزاعات الطبية، والرقابة الطبية، والمسؤولية القانونية والأحكام الختامية</td></tr></tbody></table><h3 id="_5-3-قانون-ضمان-الإسكان" tabindex="-1">5.3 قانون ضمان الإسكان <a class="header-anchor" href="#_5-3-قانون-ضمان-الإسكان" aria-label="Permalink to &quot;5.3 قانون ضمان الإسكان&quot;">​</a></h3><table tabindex="0"><thead><tr><th>رقم المادة</th><th>المحتوى الجوهري</th></tr></thead><tbody><tr><td>المادة الأولى</td><td>الغرض التشريعي: ضمان حق السكن الأساسي لجميع الكائنات الحية، بناء نظام ضمان إسكان متعدد المستويات، وتحقيق السكن للجميع</td></tr><tr><td>المواد من الثانية إلى الخامسة</td><td>تثبت مبدأ ضمان حق السكن، ومبدأ عدالة الإسكان، ومبدأ الجمع بين الإيجار والتملك، ومبدأ الإسكان المستدام</td></tr><tr><td>المواد من السادسة إلى العاشرة</td><td>تحدد نظام توفير الإسكان: المساكن العامة المؤجرة، والمساكن المؤجرة الضمانية، والمساكن ذات الملكية المشتركة، والمساكن التجارية</td></tr><tr><td>المواد من الحادية عشرة إلى الخامسة عشرة</td><td>تحدد نظام صندوق الإسكان، ونظام إعانات الإسكان، وسياسات دعم السكن الأول، والسياسات الخاصة بإسكان المزارعين</td></tr><tr><td>المواد من السادسة عشرة إلى العشرين</td><td>تحدد معايير بناء الإسكان، وتطبيق التقنيات المكانية في الإسكان، والمباني الخضراء، والمساكن الملائمة لكبار السن والخالية من العوائق</td></tr><tr><td>المواد من الحادية والعشرين إلى الخامسة والعشرين</td><td>تحدد ضبط سوق العقارات، وقواعد سوق الإيجار، وإدارة خدمات الممتلكات، وضمان صيانة الإسكان</td></tr><tr><td>المواد من السادسة والعشرين إلى الثلاثين</td><td>تحدد الرقابة على ضمان الإسكان، والمسؤولية القانونية والأحكام الختامية</td></tr></tbody></table><h3 id="_5-4-قانون-حماية-البيئة" tabindex="-1">5.4 قانون حماية البيئة <a class="header-anchor" href="#_5-4-قانون-حماية-البيئة" aria-label="Permalink to &quot;5.4 قانون حماية البيئة&quot;">​</a></h3><table tabindex="0"><thead><tr><th>رقم المادة</th><th>المحتوى الجوهري</th></tr></thead><tbody><tr><td>المادة الأولى</td><td>الغرض التشريعي: حماية البيئة وتحسينها، والوقاية من التلوث والمخاطر العامة الأخرى والسيطرة عليها، وضمان صحة الجمهور، وتعزيز بناء الحضارة الإيكولوجية الكونية، وتطوير التنمية المستدامة</td></tr><tr><td>المواد من الثانية إلى الخامسة</td><td>تثبت مبدأ أولوية الحماية، ومبدأ الوقاية أولاً، ومبدأ المعالجة الشاملة، ومبدأ المشاركة العامة، ومبدأ تحمل مسؤولية الضرر</td></tr><tr><td>المواد من السادسة إلى العاشرة</td><td>تحدد نظام الإشراف والإدارة البيئية، ونظام المعايير البيئية، ونظام تقييم الأثر البيئي، ونظام الرصد البيئي، والإدارة البيئية عبر الأبعاد</td></tr><tr><td>المواد من الحادية عشرة إلى الخامسة عشرة</td><td>تحدد الوقاية من تلوث الهواء، وتلوث المياه، وتلوث التربة، وتلوث الطاقة، وتلوث القوانين والسيطرة عليها</td></tr><tr><td>المواد من السادسة عشرة إلى العشرين</td><td>تحدد معالجة النفايات الصلبة، والوقاية من التلوث الضوضائي والسيطرة عليه، والتلوث الإشعاعي، والحماية الإيكولوجية، وحماية التنوع البيولوجي</td></tr><tr><td>المواد من الحادية والعشرين إلى الخامسة والعشرين</td><td>تحدد مراقبة الأثر البيئي لأنشطة الزراعة، والحماية الإيكولوجية لاستخراج الطاقة، والمتطلبات البيئية لعلم الآثار عبر الأبعاد</td></tr><tr><td>المواد من السادسة والعشرين إلى الثلاثين</td><td>تحدد الإفصاح عن المعلومات والمشاركة العامة، والدعاوى العامة البيئية، والمسؤولية القانونية والأحكام الختامية</td></tr></tbody></table><h3 id="_5-5-قانون-مكافحة-الاحتكار" tabindex="-1">5.5 قانون مكافحة الاحتكار <a class="header-anchor" href="#_5-5-قانون-مكافحة-الاحتكار" aria-label="Permalink to &quot;5.5 قانون مكافحة الاحتكار&quot;">​</a></h3><table tabindex="0"><thead><tr><th>رقم المادة</th><th>المحتوى الجوهري</th></tr></thead><tbody><tr><td>المادة الأولى</td><td>الغرض التشريعي: منع السلوكيات الاحتكارية وكبحها، وحماية المنافسة العادلة في السوق، ورفع كفاءة التشغيل الاقتصادي، والحفاظ على مصالح المستهلكين والمصلحة العامة للمجتمع، وتعزيز التنمية الصحية لاقتصاد السوق التكافلي</td></tr><tr><td>المواد من الثانية إلى الخامسة</td><td>تثبت المكانة الأساسية لسياسة المنافسة، ونظام مراجعة المنافسة العادلة، وحظر الاتفاقات الاحتكارية، وحظر إساءة استخدام الوضع المهيمن في السوق، وضبط تركيز المشغلين</td></tr><tr><td>المواد من السادسة إلى العاشرة</td><td>تحدد تحديد الاتفاقات الاحتكارية والإعفاء منها، والاتفاقات الاحتكارية الأفقية، والاتفاقات الاحتكارية الرأسية، والسلوكيات الاحتكارية للجمعيات الصناعية</td></tr><tr><td>المواد من الحادية عشرة إلى الخامسة عشرة</td><td>تحدد تحديد الوضع المهيمن في السوق، وأنواع السلوكيات المكونة لإساءة استخدام الوضع المهيمن، وحظر التسعير الافتراسي</td></tr><tr><td>المواد من السادسة عشرة إلى العشرين</td><td>تحدد معايير إخطار تركيز المشغلين، وإجراءات المراجعة، والشروط التقييدية الإضافية، وقرارات حظر التركيز</td></tr><tr><td>المواد من الحادية والعشرين إلى الخامسة والعشرين</td><td>تحدد الحظر الخاص لاحتكار أنظمة الزراعة: حظر احتكار طرق الزراعة، وحظر احتكار موارد الزراعة، وحظر احتكار شبكات الإرشاد</td></tr><tr><td>المواد من السادسة والعشرين إلى الثلاثين</td><td>تحدد جهة تطبيق قانون مكافحة الاحتكار، وإجراءات التحقيق، والمسؤولية القانونية، ونظام العفو والأحكام الختامية</td></tr></tbody></table><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>فهرس المواد القانونية هو خريطة استرشاد لنظام حكم القانون في حضارة التكافل المرساة. من الدستور التكافلي بوصفه القانون الأساس، إلى قانون العمل وقانون حماية المستهلك المنظمين لمعيشة الناس، ثم إلى القوانين المرافقة الخمسة، تشكل جميعها نظاماً قانونياً متكاملاً «بالدستور قائداً، وبالقوانين الأساسية عموداً فقرياً، وبالقوانين المرافقة سنداً». يضمن هذا النظام سير جميع أنشطة الحضارة التكافلية على مسار حكم القانون، ويوفر ضماناً مؤسسياً راسخاً للتقدم المشترك لعشرة آلاف عرق.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>40-共生宪法总纲 (الدستور التكافلي: المبادئ العامة)</li><li>41-共生劳动法 (قانون العمل التكافلي)</li><li>48-司法体系与裁决机制 (النظام القضائي وآلية الفصل في المنازعات)</li></ul>',28)])])}const u=d(h,[["render",l]]);export{_ as __pageData,u as default};
